-- The murlocs' questline (mod-murloc-naga): made by tools/murloc/compile.py from tools/murloc/ch*.py; edit those.
-- Safe to run again: every row of its ranges is taken out first.
DELETE FROM `creature_template` WHERE `entry` BETWEEN 976000 AND 977999;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 976000 AND 977999;
DELETE FROM `creature_text` WHERE `CreatureID` BETWEEN 976000 AND 977999;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 9760000 AND 9789999;
DELETE FROM `creature` WHERE `guid` BETWEEN 9760000 AND 9789999;
DELETE FROM `smart_scripts` WHERE (`source_type` = 0 AND `entryorguid` BETWEEN 976000 AND 977999) OR (`source_type` = 1 AND `entryorguid` BETWEEN 978000 AND 978499) OR (`source_type` = 9 AND `entryorguid` BETWEEN 97600000 AND 97849999);
DELETE FROM `game_graveyard` WHERE `ID` BETWEEN 9760 AND 9799;
DELETE FROM `npc_text` WHERE `ID` BETWEEN 976000 AND 977999;
DELETE FROM `gossip_menu` WHERE `MenuID` BETWEEN 976000 AND 977999;
DELETE FROM `gossip_menu_option` WHERE `MenuID` BETWEEN 976000 AND 977999;
DELETE FROM `npc_vendor` WHERE `entry` BETWEEN 976000 AND 977999;
DELETE FROM `trainer_spell` WHERE `TrainerId` BETWEEN 976000 AND 976999;
DELETE FROM `trainer` WHERE `Id` BETWEEN 976000 AND 976999;
DELETE FROM `creature_default_trainer` WHERE `CreatureId` BETWEEN 976000 AND 977999;
DELETE FROM `gameobject_template` WHERE `entry` BETWEEN 978000 AND 978499;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 9790000 AND 9799999;
DELETE FROM `gameobject_loot_template` WHERE `Entry` BETWEEN 978000 AND 978499;
DELETE FROM `creature_loot_template` WHERE `Comment` = 'mod-murloc-naga';
DELETE FROM `item_template` WHERE `entry` BETWEEN 979000 AND 979799;
DELETE FROM `item_dbc` WHERE `ID` BETWEEN 979000 AND 979799;
DELETE FROM `quest_template` WHERE `ID` BETWEEN 978500 AND 978999;
DELETE FROM `quest_template_addon` WHERE `ID` BETWEEN 978500 AND 978999;
DELETE FROM `quest_offer_reward` WHERE `ID` BETWEEN 978500 AND 978999;
DELETE FROM `quest_request_items` WHERE `ID` BETWEEN 978500 AND 978999;
DELETE FROM `quest_details` WHERE `ID` BETWEEN 978500 AND 978999;
DELETE FROM `creature_queststarter` WHERE `quest` BETWEEN 978500 AND 978999;
DELETE FROM `creature_questender` WHERE `quest` BETWEEN 978500 AND 978999;
DELETE FROM `gameobject_queststarter` WHERE `quest` BETWEEN 978500 AND 978999;
DELETE FROM `gameobject_questender` WHERE `quest` BETWEEN 978500 AND 978999;
DELETE FROM `quest_poi` WHERE `QuestID` BETWEEN 978500 AND 978999;
DELETE FROM `quest_poi_points` WHERE `QuestID` BETWEEN 978500 AND 978999;
DELETE FROM `conditions` WHERE `Comment` = 'mod-murloc-naga';
DELETE FROM `spell_area` WHERE `spell` BETWEEN 979800 AND 979899 OR (`racemask` = 262144 AND `area` NOT IN (148, 331));
DELETE FROM `gameobjectdisplayinfo_dbc` WHERE `ID` BETWEEN 9800 AND 9999;
-- Spells the story's quests teach (the module, src/MurlocNaga.cpp, teaches them as each is handed in).
CREATE TABLE IF NOT EXISTS `murloc_naga_story_learn` (`quest` INT UNSIGNED NOT NULL, `spell` INT UNSIGNED NOT NULL, PRIMARY KEY (`quest`, `spell`));
DELETE FROM `murloc_naga_story_learn`;
-- The tribe's graveyards, as the module (src/MurlocNaga.cpp) chooses them for a murloc whose story isn't done.
CREATE TABLE IF NOT EXISTS `murloc_naga_graveyards` (`id` INT UNSIGNED NOT NULL PRIMARY KEY, `map` INT UNSIGNED NOT NULL, `x` FLOAT NOT NULL, `y` FLOAT NOT NULL, `z` FLOAT NOT NULL, `from_quest` INT UNSIGNED NOT NULL, `until_quest` INT UNSIGNED NOT NULL);
DELETE FROM `murloc_naga_graveyards`;
-- What the module (src/MurlocNaga.cpp) reads of the story: its quests' range, and the last quest, which opens
-- the Alliance's and everyone's quests to a murloc.
CREATE TABLE IF NOT EXISTS `murloc_naga_story` (`name` VARCHAR(32) NOT NULL PRIMARY KEY, `value` INT UNSIGNED NOT NULL);
